//! 🗜️ Explicit RFC1950 header, bounded raw codec and hexadecimal carrier under one native owner.
use super::{DeflateSnapshot,DeflateLevelHint};
use crate::store;
use store::sqlite_snapshot::{SqliteSnapshotControl,SqliteSnapshotPhase,SnapshotEncoding};
use semio_framework_value::{NativeDecodeControl,NativeEncodeControl,ValueError,native_decoding::NativeDecodeProgress,native_encoding::NativeEncodeProgress};
use semio_framework_deflate::{Inflater,InflateOutcome,RetainedInflateCloseStep,DeflateEncodeControl,DeflateEncodeProgress};
struct History(Inflater);
impl Drop for History{fn drop(&mut self){let mut stalled=0;loop{match self.0.close_retained_step(256,usize::MAX){RetainedInflateCloseStep::Complete=>break,RetainedInflateCloseStep::Pending{released_items,released_bytes}=>{if released_items==0&&released_bytes==0{stalled+=1;assert!(stalled<256,"Deflate history retirement made no progress");}else{stalled=0;}}}}assert!(self.0.retained_terminal_is_empty());}}
fn digit(ch:char)->Result<u8,String>{ch.to_digit(16).and_then(|value|u8::try_from(value).ok()).ok_or_else(||"invalid Deflate hexadecimal digit".into())}
fn hex(text:&str,control:&mut NativeDecodeControl<'_>)->Result<Vec<u8>,String>{
