/// 🫧️ Bare RFC1950 expansion preserves one caller-owned control across both physical passes.
pub fn decompress_zlib(bytes:&[u8],maximum_output:usize,control:&mut NativeDecodeControl<'_>)->Result<Vec<u8>,String> {
 if bytes.len()<6{return Err("zlib stream too short".into())}let cmf=bytes[0];let flg=bytes[1];if cmf&15!=8||cmf>>4>7{return Err("unsupported zlib method or window".into())}if !(u16::from(cmf)*256+u16::from(flg)).is_multiple_of(31){return Err("zlib CMF/FLG check failed".into())}if flg&32!=0{return Err("bare zlib consumer has no preset dictionary authority".into())}
